88	fn show_waste(json: bool) -> Result<()> {
89	    let db_path = paths::db_path();
90	    let session_id = codeflow_core::util::session_id();
91	
92	    let session_log = codeflow_core::session::SessionLog::open(&db_path, &session_id)?;
93	    let analyzer = codeflow_core::waste::WasteAnalyzer::new(&session_log);
94	    let report = analyzer.analyze()?;
95	
96	    if json {
97	        println!("{}", serde_json::to_string_pretty(&report)?);
98	        return Ok(());
99	    }
100	
101	    println!("CODEFLOW Waste Report");
102	    println!("═══════════════════════════════════════");
103	    println!();
104	
105	    if report.patterns.is_empty() {
106	        println!("  No waste patterns detected this session.");
107	        return Ok(());
108	    }
109	
110	    println!(
111	        "  Token waste detected: ~{} tokens ({:.1}% of session)",
112	        format_number(report.total_wasted_tokens),
113	        report.waste_percentage
114	    );
115	    println!();
116	
117	    let re_reads: Vec<_> = report
118	        .patterns
119	        .iter()
120	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::ReReadWaste { .. }))
121	        .collect();
122	    if !re_reads.is_empty() {
123	        println!("  Re-read waste ({} files):", re_reads.len());
124	        for p in &re_reads {
125	            if let codeflow_core::waste::WastePattern::ReReadWaste {
126	                file_path,
127	                read_count,
128	                redundant_count,
129	                tokens_wasted,
130	            } = p
131	            {
132	                println!(
133	                    "    {:<28} read {}x  →  {} redundant  (~{} tokens)",
134	                    truncate(file_path, 28),
135	                    read_count,
136	                    redundant_count,
137	                    format_number(*tokens_wasted)
138	                );
139	            }
140	        }
141	        println!();
142	    }
143	
144	    let redundant: Vec<_> = report
145	        .patterns
146	        .iter()
147	        .filter(|p| {
148	            matches!(
149	                p,
150	                codeflow_core::waste::WastePattern::RedundantCommand { .. }
151	            )
152	        })
153	        .collect();
154	    if !redundant.is_empty() {
155	        println!("  Redundant commands ({} patterns):", redundant.len());
156	        for p in &redundant {
157	            if let codeflow_core::waste::WastePattern::RedundantCommand {
158	                command_preview,
159	                run_count,
160	                redundant_count,
161	                tokens_wasted,
162	            } = p
163	            {
164	                println!(
165	                    "    {:<28} ran {}x  →  {} redundant  (~{} tokens)",
166	                    truncate(command_preview, 28),
167	                    run_count,
168	                    redundant_count,
169	                    format_number(*tokens_wasted)
170	                );
171	            }
172	        }
173	        println!();
174	    }
175	
176	    let failed: Vec<_> = report
177	        .patterns
178	        .iter()
179	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::FailedSearch { .. }))
180	        .collect();
181	    if !failed.is_empty() {
182	        println!("  Failed searches ({} patterns):", failed.len());
183	        for p in &failed {
184	            if let codeflow_core::waste::WastePattern::FailedSearch {
185	                pattern_preview,
186	                attempt_count,
187	            } = p
188	            {
189	                println!(
190	                    "    {}  →  0 results (tried {}x)",
191	                    truncate(pattern_preview, 40),
192	                    attempt_count
193	                );
194	            }
195	        }
196	        println!();
197	    }
198	
199	    let spam: Vec<_> = report
200	        .patterns
201	        .iter()
202	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::GlobSpam { .. }))
203	        .collect();
204	    if !spam.is_empty() {
205	        println!("  Glob spam ({} patterns):", spam.len());
206	        for p in &spam {
207	            if let codeflow_core::waste::WastePattern::GlobSpam {
208	                pattern_preview,
209	                run_count,
210	                redundant_count,
211	            } = p
212	            {
213	                println!(
214	                    "    {}  →  ran {}x ({} redundant)",
215	                    truncate(pattern_preview, 40),
216	                    run_count,
217	                    redundant_count
218	                );
219	            }
220	        }
221	        println!();
222	    }
223	
224	    let unused: Vec<_> = report
225	        .patterns
226	        .iter()
227	        .filter(|p| {
228	            matches!(
229	                p,
230	                codeflow_core::waste::WastePattern::LargeUnusedRead { .. }
231	            )
232	        })
233	        .collect();
234	    if !unused.is_empty() {
235	        println!("  Possibly unused large reads ({}):", unused.len());
236	        for p in &unused {
237	            if let codeflow_core::waste::WastePattern::LargeUnusedRead {
238	                file_path,
239	                token_count,
240	            } = p
241	            {
242	                println!(
243	                    "    {} (~{} tokens) read but not referenced later",
244	                    truncate(file_path, 30),
245	                    format_number(*token_count)
246	                );
247	            }
248	        }
249	        println!();
250	    }
251	
252	    println!("  Tip: CODEFLOW Read Dedup automatically prevents re-read waste.");
253	    println!("       Run `codeflow stats` to see your savings.");
254	
255	    Ok(())
256	}
