268	fn truncate(s: &str, max: usize) -> String {
269	    if s.chars().count() > max {
270	        let truncated: String = s.chars().take(max - 1).collect();
271	        format!("{}…", truncated)
272	    } else {
273	        s.to_string()
274	    }
275	}
